rows=[]
for i,(t,l,s,e,ex,xs) in enumerate(G):
    exj=json.dumps([{"en":a,"pt":b} for a,b in ex], ensure_ascii=False)
    xsj=json.dumps([{"prompt":p,"options":o,"answer":a,"explanation":x} for p,o,a,x in xs], ensure_ascii=False)
    rows.append(f"(null, {q(t)}, '{l}', {q(s)}, {q(e)}, {q(exj)}::jsonb, {q(xsj)}::jsonb, {i})")
out.append(",\n".join(rows)+";\n")

